rating = {"Spice Route": 4.3, "Green Leaf": 4.1, "Biryani Box": 3.8,
          "Annapurna Meals": 3.6, "Royal Handi": 4.6, "Dum Corner": 3.9}
veg = {"Green Leaf", "Annapurna Meals"}

def is_rated_4(name):
    return rating[name] >= 4.0

def is_veg(name):
    return name in veg

print(list(filter(is_rated_4, rating)))
print(list(filter(is_veg, rating)))
